// TH18 v1.00a st04bs.ecl.txt::Boss1 (B:56-189), ranks 0-3. Non-spell, no source timeout.
// Source Boss1 t0 (B:56 entry) = card frame 1. The 120f practice buffer covers card1..120;
// source wait80 (B:63) then puts the first at() ring wave on card frame 201.
// TIME_LIMIT/CARD_END are a local training window: 8 main-loop ring waves plus tail.
const TIME_LIMIT: int = 2400;
const CARD_END: int = 2401; // phase_begin executes on card1 and times out 2400f later.

// Needed rows from the TH18 bullet word table (engine/touhou-bullets.ecl).
const TH18_BIG_BALL: int = 640;      // source etSprite type18
const TH18_DROPLET: int = 896;       // source etSprite type34
const TH18_YIN_YANG_R: int = 1056;   // source etSprite type44
const TH18_YIN_YANG_L: int = 1072;   // source etSprite type45

// B:100-103 / B:121-124: ANGLE_ACCEL type8 a360 r0.005/f s0.013962634rad/f.
// r is the per-frame scalar speed gain; s is the per-frame angle gain (0.8deg=146bam).
// B:101/122 OFFSCREEN type256 a600 b0. ANIM a1 only contributes the 4*velocity birth
// retraction, carried by sh_dist below (birth animation/window omitted per policy).
xformdef RING_MOTION {
    offscreen_keep(600);
    set_ang_vel(146);
    set_accel(0.005fx);
    wait(360);
    set_ang_vel(0);
    set_accel(0fx);
}

// B:148-150: ANIM a1; then WAIT type0x80000000 a120; then VELTIME type0x200000
// a120 r3.0 with s=-9999994 (keep current angle).
xformdef DROPLET_MOTION {
    wait(120);
    step_speed(3fx, 120);
}

// B:79-127. at() is called synchronously by Boss1; it reinitialises et0/et1 each call.
sub b1_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 5;
    if rank == 1 { n = 10; }
    if rank == 2 { n = 13; }
    if rank == 3 { n = 16; }

    // B:84-104: et0 type44 color1, mode3 fixed ring, base -pi/2, speed1.5, M1.
    sh_reset(0);
    sh_sprite(0, TH18_YIN_YANG_R, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, -90deg, 0deg);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx); // ANIM a1: -4*1.5
    sh_xform(0, RING_MOTION);
    sh_fire(0);

    // B:105-125: et1 type45 color2, same geometry, opposite angle acceleration.
    sh_reset(1);
    sh_sprite(1, TH18_YIN_YANG_L, 2);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, n, 1);
    sh_angle(1, -90deg, 0deg);
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, -6fx); // ANIM a1: -4*1.5
    sh_xform(1, RING_MOTION);
    sh_fire(1);
}

// B:129-166. async at2: first run next frame, wait60, then 80 cycles of 5 random-base
// droplet rings 20f apart plus wait120 (220f per cycle).
async sub b1_at2() {
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    if rank == 1 { n = 24; }
    if rank == 2 { n = 30; }
    if rank == 3 { n = 40; }

    wait(60); // B:132
    sh_reset(0);
    sh_sprite(0, TH18_DROPLET, 13);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, 0.6fx, 0fx);
    sh_dist(0, -2.4fx); // ANIM a1: -4*0.6
    sh_xform(0, DROPLET_MOTION);

    for cycle in 0..80 { // B:151/164: $A=80, post-decrement
        for shot in 0..5 { // B:154/161: $B=5, post-decrement
            if $frame >= CARD_END { return; }
            // B:157/158: etAngle(2,%RANDRAD,0); etOn(2); wait20.
            sh_angle(0, (rand(65536)-32768) as angle, 0deg);
            sh_fire(0);
            wait(20);
        }
        if $frame >= CARD_END { return; }
        wait(120);
    }
}

// B:168-188. async at3: et3 type18 color6, mode2 aimed ring, count1, speed1.6,
// fires only when DIST_PLAYER <= 190, then waits 50; $A=8000 iterations.
async sub b1_at3() {
    for i in 0..8000 {
        if $frame >= CARD_END { return; }
        var dx: fx = $player_x-$self_x;
        var dy: fx = $player_y-$self_y;
        if dist(dx, dy) <= 190fx {
            var a: angle = atan2(dy, dx);
            // ANIM a1: -4*1.6 along the firing direction.
            var sx: fx = $self_x-6.4fx*cos(a);
            var sy: fx = $self_y-6.4fx*sin(a);
            _ = fire(TH18_BIG_BALL, 6, sx, sy, 1.6fx, a, none, none);
        }
        wait(50);
    }
}

// B:56-77. Source wait80 then spawn at2/at3 async and enter the synchronous at() loop.
async sub b1_boss() {
    set_invuln(65535);          // practice shell
    set_hitbox(24fx);           // B:27 setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);          // B:26 setHurtbox(40,40) -> radius 20

    wait(120);                  // practice buffer, card1..120
    wait(80);                   // B:63
    spawn b1_at2();
    spawn b1_at3();
    loop {
        if $frame >= CARD_END { break; }
        b1_at();
        wait(140);
        if $frame >= CARD_END { break; }
        card_move_rand();       // B:72 moveRand(60,4,0.7)
        card_wait(160, CARD_END);
    }
    loop { wait(600); }         // keep the real enemy for the bullet tail
}

// Phase holder only; the boss attack runs on the real enemy below.
async sub b1_phase() {
    wait(TIME_LIMIT);
    loop { wait(600); }
}

// Extra control enemy at (0,0), no body collision; real boss keeps source judgment.
async sub b1_encounter() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, b1_phase, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    // Source Boss common entry B:14 puts the boss at (0,128); limit B:28 is in movement.ecl.
    _ = spawn_enemy(0fx, 128fx, 3400, 0, 0, 0, b1_boss);
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, b1_encounter);
    loop { wait(600); }
}

// TH18 v1.00a Boss1 moveRand(60,4,0.7) with moveLimit(0,128,280,64) from B:28.
// Native limit: x in [-140,140], y in [96,160]; direction inner box x +-70, y 112..144.
// int slot0 = next step count, fx slot0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int, until: int) {
    for i in 0..frames {
        if $frame >= until { return; }
        wait(1);
        card_arm_next_step();
    }
}
